import sys
from collections import Counter

def main():
    H, W = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]

    row_signatures = ["".join(sorted(row)) for row in grid]
    count = Counter(row_signatures)

    if H % 2 == 0:
        for v in count.values():
            if v % 2 != 0:
                print("NO")
                return
    else:
        odd_count = 0
        for v in count.values():
            if v % 2 == 1:
                odd_count += 1
                if odd_count > 1:
                    print("NO")
                    return
        if odd_count != 1:
            print("NO")
            return

        middle_signature = None
        for sig, cnt in count.items():
            if cnt == 1:
                middle_signature = sig
                break

        freq = Counter(middle_signature)
        odd_chars = sum(1 for c in freq.values() if c % 2 != 0)
        if W % 2 == 0 and odd_chars != 0:
            print("NO")
            return
        if W % 2 == 1 and odd_chars != 1:
            print("NO")
            return

    print("YES")

